/// <summary>
/// Data contract class for sales picking list generation service
/// </summary>
[DataContractAttribute]
class METSalesPickingListGenerationContract
{
    container       salesOrderList;
    //CB123 SalesOrderExtractScreenforCSD -start
    container       csdSalesOrderList;
}

Method.Source:
    //CB123 SalesOrderExtractScreenforCSD -end

    /// <summary>
    /// parm method for sales order list container which contains sales order and OSCCode list
    /// </summary>
    /// <param name = "_salesOrderList">sales order list</param>
    /// <returns>sales order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmSalesOrderList(container _salesOrderList = salesOrderList)
    {
        salesOrderList = _salesOrderList;

        return salesOrderList;
    }

    /// <summary>
    /// parm method for csd sales order list container which contains sales order and OSCCode list
    /// </summary>
    /// <param name = "_csdSalesOrderList"> csd sales order list</param>
    /// <returns>csd sales order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmCSDSalesOrderList(container _csdSalesOrderList = csdSalesOrderList)
    {
        csdSalesOrderList = _csdSalesOrderList;

        return csdSalesOrderList;
    }
